def finding(row,n,refs):
    fid,name,kind,required=row; ks=[kind,KINDS[(n*5)%len(KINDS)],KINDS[(n*11+3)%len(KINDS)]]
    for j in (1,2):
        while ks[j] in ks[:j]: ks[j]=KINDS[(KINDS.index(ks[j])+1)%len(KINDS)]
    low=name.lower()
    qs=[("q01",f"What continuity-capability identities, classes, roles, versions, values and explicit unknowns establish {low}?",ks[0],["identities and classifications","roles, versions and values","explicit unknowns"]),("q02",f"Which authority, source, method, evidence, event time, knowledge time, confidence and limits support {low}?",ks[1],["authority and source","method and evidence","times, confidence and limits"]),("q03",f"How may {low} be validated, exercised, activated, challenged, corrected, related, retained or disposed without losing history?",ks[2],["validation, exercise and activation","challenge and correction","relations, retention and disposition"])]
    return {"id":fid,"name":name,"description":f"Records {low} as source-qualified continuity context while preserving external master ownership and distinguishing target, request, execution and verification.","source_refs":refs,"questions":[{"id":f"{fid}-{q[0]}","text":q[1],"kind":q[2],"answer_data":q[3]} for q in qs],"data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Structured data for {low} with authority, time, state, evidence and access marking.","value_kind":"collection","cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],"artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Versioned evidence-bearing continuity record for {low}.","media_or_form":["logical continuity assertion","plan, event, evidence, decision or outcome record"],"serial":True,"identity_strategy":f"Continuity capability ID plus {fid} assertion or event ID; title, date, timestamp and digest never identify the capability alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    out=[]; n=0
    for bid,bname,rat,layers in ROWS:
        ls=[]
        for lid,lname,refs,finds in layers:
            fs=[]
            for f in finds: n+=1; fs.append(finding(f,n,refs))
            ls.append({"id":lid,"name":lname,"description":f"Groups continuity context for {lname.lower()}.","source_refs":refs,"findings":fs})
        out.append({"id":bid,"name":bname,"description":f"Groups governed context for {bname.lower()}.","rationale":rat+".","source_refs":sorted({x for l in layers for x in l[2]}),"layers":ls})
    return {"bundles":out}

